-- Sprint 79: enrich the canonical site_visits table; no parallel scheduling engine.
alter table public.site_visits drop constraint if exists site_visits_status_check;
alter table public.site_visits add column if not exists contact_id uuid,add column if not exists project_id uuid,add column if not exists tower_id uuid,add column if not exists unit_id uuid,add column if not exists customer_label text,add column if not exists agent_label text,add column if not exists project_label text,add column if not exists tower_label text,add column if not exists unit_label text,add column if not exists duration_minutes integer not null default 60,add column if not exists visit_type text not null default'initial',add column if not exists priority text not null default'medium',add column if not exists agenda jsonb not null default'[]',add column if not exists visitor_instructions text,add column if not exists documents jsonb not null default'[]',add column if not exists checklist jsonb not null default'[]',add column if not exists reminder_timeline jsonb not null default'[]',add column if not exists arrival_at timestamptz,add column if not exists departure_at timestamptz;
alter table public.site_visits add constraint site_visits_status_check check(status in('scheduled','confirmed','checked_in','completed','cancelled','no_show','rescheduled'));alter table public.site_visits add constraint site_visits_type_check check(visit_type in('initial','follow_up','virtual_tour','final_inspection'));alter table public.site_visits add constraint site_visits_priority_check check(priority in('low','medium','high','urgent'));alter table public.site_visits add constraint site_visits_duration_check check(duration_minutes between 15 and 1440);
create table if not exists public.site_visit_feedback(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),visit_id uuid not null references public.site_visits(id) on delete cascade,rating integer not null check(rating between 1 and 5),agent_notes text,interested_unit_ids uuid[] not null default'{}',budget_update numeric,currency char(3),preferred_configuration text,objections text[] not null default'{}',competitor_projects text[] not null default'{}',probability_change integer check(probability_change between -100 and 100),created_by uuid not null default auth.uid(),created_at timestamptz not null default now());
create table if not exists public.site_visit_audit(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),visit_id uuid not null references public.site_visits(id),action text not null,actor_id uuid default auth.uid(),actor_label text not null default'Authorized user',metadata jsonb not null default'{}',occurred_at timestamptz not null default now());
create table if not exists public.site_visit_follow_up_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),visit_id uuid not null references public.site_visits(id),kind text not null check(kind in('task','reminder','summary','next-property','opportunity-stage','second-visit','email-draft','whatsapp-draft')),status text not null default'pending',recommendation_only boolean not null default false,created_by uuid not null default auth.uid(),created_at timestamptz not null default now());
create index if not exists site_visits_schedule_v2_idx on public.site_visits(organization_id,workspace_id,assigned_agent_id,starts_at,ends_at)where deleted_at is null;create index if not exists site_visit_feedback_visit_idx on public.site_visit_feedback(workspace_id,visit_id,created_at desc);create index if not exists site_visit_audit_visit_idx on public.site_visit_audit(workspace_id,visit_id,occurred_at desc);create index if not exists site_visit_follow_up_idx on public.site_visit_follow_up_requests(workspace_id,status,created_at);
create or replace function public.site_visit_member(p_organization_id uuid,p_workspace_id uuid)returns boolean language sql stable security definer set search_path=public as $$select public.is_organization_member(p_organization_id)and exists(select 1 from workspace_members wm where wm.organization_id=p_organization_id and wm.workspace_id=p_workspace_id and wm.user_id=auth.uid()and wm.status='active')$$;
create or replace function public.site_visit_can_manage(p_organization_id uuid,p_workspace_id uuid)returns boolean language sql stable security definer set search_path=public as $$select public.site_visit_member(p_organization_id,p_workspace_id)and exists(select 1 from organization_members om left join roles r on r.id=om.role_id where om.organization_id=p_organization_id and om.user_id=auth.uid()and om.status='active'and r.code in('organization_owner','organization_admin','administrator','sales_manager','sales_agent','project_manager'))$$;
alter table public.site_visit_feedback enable row level security;alter table public.site_visit_audit enable row level security;alter table public.site_visit_follow_up_requests enable row level security;
do $$declare t text;begin foreach t in array array['site_visit_feedback','site_visit_audit','site_visit_follow_up_requests']loop execute format('create policy %I on public.%I for select to authenticated using(public.site_visit_member(organization_id,workspace_id))',t||'_read',t);execute format('create policy %I on public.%I for insert to authenticated with check(public.site_visit_can_manage(organization_id,workspace_id))',t||'_create',t);execute format('create policy %I on public.%I for update to authenticated using(public.site_visit_can_manage(organization_id,workspace_id)) with check(public.site_visit_can_manage(organization_id,workspace_id))',t||'_update',t);execute format('create policy %I on public.%I for delete to authenticated using(public.site_visit_can_manage(organization_id,workspace_id))',t||'_delete',t);end loop;end$$;
drop policy if exists site_visits_workspace_write on public.site_visits;create policy site_visits_workspace_write on public.site_visits for update to authenticated using(public.site_visit_can_manage(organization_id,workspace_id))with check(public.site_visit_can_manage(organization_id,workspace_id));
create or replace function public.site_visit_agent_availability(p_workspace_id uuid)returns table(agent_id uuid,agent_name text,available boolean,visits_today bigint,workload integer,languages text[],region text,manager text)language sql stable security definer set search_path=public as $$select wm.user_id,coalesce(nullif(u.raw_user_meta_data->>'full_name',''),u.email,'Agent'),not exists(select 1 from site_visits sv where sv.workspace_id=p_workspace_id and sv.assigned_agent_id=wm.user_id and sv.status in('scheduled','confirmed','checked_in')and tstzrange(sv.starts_at,coalesce(sv.ends_at,sv.starts_at+interval'60 minutes'))&&tstzrange(now(),now()+interval'60 minutes')),count(sv.id)filter(where sv.starts_at::date=current_date),least(100,(count(sv.id)filter(where sv.starts_at>=date_trunc('week',now()))*10)::integer),array['English']::text[],'Assigned region','Assigned manager'from workspace_members wm join auth.users u on u.id=wm.user_id left join site_visits sv on sv.workspace_id=wm.workspace_id and sv.assigned_agent_id=wm.user_id where wm.workspace_id=p_workspace_id and wm.user_id=auth.uid()and wm.status='active'group by wm.user_id,u.raw_user_meta_data,u.email$$;
create or replace function public.manage_site_visit_lifecycle(p_workspace_id uuid,p_visit_id uuid,p_expected_version integer,p_action text,p_payload jsonb default'{}')returns void language plpgsql security definer set search_path=public as $$declare v_org uuid;v site_visits%rowtype;v_next text;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not site_visit_can_manage(v_org,p_workspace_id)then raise exception'not authorized';end if;select*into v from site_visits where id=p_visit_id and organization_id=v_org and workspace_id=p_workspace_id and deleted_at is null for update;if v.id is null or v.version<>p_expected_version then raise exception'visit changed; refresh and retry';end if;
if p_action='confirm'then v_next:='confirmed';elsif p_action='check-in'then v_next:='checked_in';elsif p_action='complete'then v_next:='completed';elsif p_action='cancel'then v_next:='cancelled';elsif p_action='no-show'then v_next:='no_show';elsif p_action='reschedule'then v_next:='rescheduled';else v_next:=v.status;end if;
if p_action='check-in'then update site_visits set status=v_next,arrival_at=coalesce(nullif(p_payload->>'arrivalAt','')::timestamptz,now()),updated_at=now(),updated_by=auth.uid(),version=version+1 where id=v.id;elsif p_action in('confirm','complete','cancel','no-show','reschedule')then update site_visits set status=v_next,departure_at=case when p_action='complete'then coalesce(nullif(p_payload->>'departureAt','')::timestamptz,now())else departure_at end,updated_at=now(),updated_by=auth.uid(),version=version+1 where id=v.id;elsif p_action='feedback'then insert into site_visit_feedback(organization_id,workspace_id,visit_id,rating,agent_notes)values(v_org,p_workspace_id,v.id,greatest(1,least(5,(p_payload->>'rating')::integer)),nullif(p_payload->>'notes',''));elsif p_action='follow-up'then insert into site_visit_follow_up_requests(organization_id,workspace_id,visit_id,kind)values(v_org,p_workspace_id,v.id,'task'),(v_org,p_workspace_id,v.id,'reminder'),(v_org,p_workspace_id,v.id,'summary'),(v_org,p_workspace_id,v.id,'next-property');elsif p_action in('reserve-unit','release-unit')then if v.unit_id is null then raise exception'no unit linked';end if;perform transition_property_unit(p_workspace_id,v.unit_id,(select status from property_units where id=v.unit_id),case when p_action='reserve-unit'then'reserved'else'available'end,null,false);else raise exception'unsupported action';end if;
insert into site_visit_audit(organization_id,workspace_id,visit_id,action,metadata)values(v_org,p_workspace_id,v.id,'visit.'||p_action,p_payload);insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id)values(v_org,p_workspace_id,'site_visit.'||p_action,'Site visit '||replace(p_action,'-',' '),auth.uid(),'site_visit',v.id);if p_action='complete'then insert into site_visit_follow_up_requests(organization_id,workspace_id,visit_id,kind)values(v_org,p_workspace_id,v.id,'task'),(v_org,p_workspace_id,v.id,'reminder'),(v_org,p_workspace_id,v.id,'summary');end if;end$$;
revoke all on function public.manage_site_visit_lifecycle(uuid,uuid,integer,text,jsonb)from public;grant execute on function public.manage_site_visit_lifecycle(uuid,uuid,integer,text,jsonb)to authenticated;grant execute on function public.site_visit_agent_availability(uuid)to authenticated;
